    top_extent = [[0]*W for _ in range(H)]  # max continuous same value going up
    bottom_extent = [[0]*W for _ in range(H)]  # max continuous same value going down
    left_extent = [[0]*W for _ in range(H)]  # max continuous same value going left
    right_extent = [[0]*W for _ in range(H)]  # max continuous same value going right

    # Fill in 4 directions for each cell
    for val in set(cell for row in grid for cell in row):
        for r in range(H):
            run = 0
            for c in range(W):
                if grid[r][c] == val:
                    run += 1
                    bottom_extent[r][c] = run
                else:
                    bottom_extent[r][c] = 0

        for r in range(H-1, -1, -1):
